func grid_stats(grid: Array):
    var total = 0
    var largest = grid[0][0]
    var even = 0
    for row in grid:
        for value in row:
            total += value
            if value > largest:
                largest = value
            if value % 2 == 0:
                even += 1
    return [total, largest, even]

