# Scrivi sales_report(inventory, sales) sopra _ready().
func sales_report(inventory: Dictionary, sales: Dictionary) -> String:
    var revenue = 0.0
    for item in sales:
        if not inventory.has(item):
            print("Errore: articolo '%s' non trovato." % item)
            continue
        var qty = sales[item]
        if inventory[item]["stock"] < qty:
            print("Errore: scorte insufficienti per '%s'." % item)
            continue
        inventory[item]["stock"] -= qty
        revenue += inventory[item]["price"] * qty
    return "Ricavo totale: %.2f" % revenue

